/** Bounded actual-match native bee, loot, hive and sting fixtures; no participant is killed. */
public final class BeeDropChecks {
    private BeeDropChecks() { }
    private static State running,stopping,stoppedFixture;
    private static String stopEpoch;
    private static ItemEntity stopToken;
    private static List<Bee> stopBees=List.of();
    private static BeehiveBlockEntity stopHive;
    private static int stopXp;
    private static void require(boolean ok,String text){if(!ok)throw new IllegalStateException("Bees drop: "+text);}
    private static net.minecraft.nbt.CompoundTag saved(Entity actor,ServerLevel level){var out=net.minecraft.world.level.storage.TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,level.registryAccess());actor.saveWithoutId(out);return out.buildResult();}
    private static ItemEntity token(ServerLevel level,Vec3 at,int count,LivingEntity author,LbcBeeDropItem.Kind kind){
        var item=new ItemEntity(level,at.x,at.y,at.z,new ItemStack(kind.item(),count));if(author!=null)item.setThrower(author);item.setNoGravity(true);item.setDeltaMovement(Vec3.ZERO);item.setPickUpDelay(1000);require(level.addFreshEntity(item),"native token admission");return item;
    }
    private static final class State implements AutoCloseable {
        final GameController game;final ServerLevel level;final ServerPlayer alpha,beta;
        final GameChecks.WandThirdPlayerState alphaState,betaState;final Vec3 origin;final BlockPos center;
        final Map<BlockPos,MapManager.BlockSnapshot> blocks=new LinkedHashMap<>();final Set<Long> forced=new HashSet<>();
        final Set<Entity> existing=Collections.newSetFromMap(new IdentityHashMap<>());final List<ItemEntity> tokens=new ArrayList<>();
        final Set<Bee> mine=Collections.newSetFromMap(new IdentityHashMap<>());final Map<Bee,Vec3> frozen=new IdentityHashMap<>();
        final boolean mobDrops,blockDrops;final int alphaKills,betaKills;final double alphaLuck,betaLuck;
        ItemEntity stack,paused,unloaded;int phase,lastTick,wait;
        State(GameController game){this.game=game;level=game.maps().level();alpha=game.server().getPlayerList().getPlayer(GameChecks.offlineUuid("TestAlpha"));beta=game.server().getPlayerList().getPlayer(GameChecks.offlineUuid("TestBeta"));
            require(game.playing() && alpha!=null && beta!=null && game.allowDamage(beta),"two actual match participants");alphaState=new GameChecks.WandThirdPlayerState(alpha,game.items().mana());betaState=new GameChecks.WandThirdPlayerState(beta,game.items().mana());
            origin=new Vec3(Math.floor(alpha.getX()/16)*16+8.37,270.7,Math.floor(alpha.getZ()/16)*16+8.81);center=BlockPos.containing(origin);level.getAllEntities().forEach(existing::add);
            mobDrops=level.getGameRules().get(GameRules.MOB_DROPS);blockDrops=level.getGameRules().get(GameRules.BLOCK_DROPS);alphaKills=kills(alpha);betaKills=kills(beta);
            alphaLuck=alpha.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.LUCK).getBaseValue();betaLuck=beta.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.LUCK).getBaseValue();}
        int kills(ServerPlayer player){return player.getStats().getValue(net.minecraft.stats.Stats.CUSTOM.get(net.minecraft.stats.Stats.MOB_KILLS));}
        void initialize(){
            for(var p:BlockPos.betweenClosed(center.offset(-4,-2,-4),center.offset(4,5,4))){var pos=p.immutable();long key=net.minecraft.world.level.ChunkPos.pack(pos.getX()>>4,pos.getZ()>>4);if(!level.getForceLoadedChunks().contains(key)){forced.add(key);level.setChunkForced(pos.getX()>>4,pos.getZ()>>4,true);}level.getChunkAt(pos);blocks.put(pos,game.maps().snapshot(pos));}
            for(var p:List.of(alpha,beta)){p.closeContainer();p.getInventory().clearContent();p.removeAllEffects();p.setGameMode(GameType.SURVIVAL);p.setNoGravity(true);p.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(1000);p.setHealth(1000);p.setAbsorptionAmount(0);p.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.LUCK).setBaseValue(0);}
            alpha.teleportTo(level,origin.x+20,origin.y,origin.z,Set.of(),0,0,true);beta.teleportTo(level,origin.x+22,origin.y,origin.z,Set.of(),0,0,true);
            level.getGameRules().set(GameRules.MOB_DROPS,true,game.server());level.getGameRules().set(GameRules.BLOCK_DROPS,true,game.server());reset();lastTick=game.server().getTickCount();}
        void reset(){clearMine();for(var p:blocks.keySet()){if(level.getBlockEntity(p) instanceof net.minecraft.world.Container c)c.clearContent();level.setBlock(p,Blocks.AIR.defaultBlockState(),818);}}
        void capture(){for(var b:game.items().beeDrops().snapshot())if(!existing.contains(b) && !b.isRemoved())mine.add(b);}
        void clearMine(){capture();new ArrayList<>(mine).forEach(Entity::discard);mine.clear();}
        ItemEntity drop(int count){var t=token(level,origin,count,alpha,LbcBeeDropItem.Kind.NORMAL);tokens.add(t);return t;}
        List<Bee> batch(){clearMine();var t=drop(2);t.setTarget(beta.getUUID());t.setYRot(37);t.setXRot(23);
            require(game.items().beeDrops().ready(t),"actual-tick resident service admission");require(game.items().specialDrops().spawn(t) && t.getItem().getCount()==1,"dispatcher one unit debit");require(!game.items().specialDrops().spawn(t) && t.getItem().getCount()==1,"same tick duplicate guard");t.discard();capture();var bees=new ArrayList<>(mine);require(bees.size()==7,"seven native independent bees");return bees;}
        void defaults(List<Bee> bees){var counts=new HashMap<Vec3,Integer>();for(var b:bees){counts.merge(b.position(),1,Integer::sum);var tag=saved(b,level);
                require(b.getClass()==Bee.class && b.hasNectar() && !b.hasStung() && !b.isBaby() && !b.isNoAi() && !b.isNoGravity() && b.getTarget()==null && !b.isPersistenceRequired() && b.getHealth()==b.getMaxHealth(),"native bee defaults and nectar");
                require(b.getDeltaMovement().equals(Vec3.ZERO) && b.getYRot()==0 && b.getXRot()==0 && !b.hasHive(),"source zero motion/rotation and no invented hive binding");
                require(tag.getStringOr("DeathLootTable","").equals("lbc:honey") && game.items().beeDrops().owner(b)==alpha && game.items().currentEpoch(b),"native custom death loot, actual thrower and epoch");}
            require(counts.size()==5 && counts.getOrDefault(origin.add(0,2,0),0)==3,"three overlapping upper summons");for(var d:List.of(new Vec3(0,1,1),new Vec3(0,1,-1),new Vec3(1,1,0),new Vec3(-1,1,0)))require(counts.getOrDefault(origin.add(d),0)==1,"exact fractional token cardinal summon "+d);
            require(level.getBlockState(center).is(Blocks.OAK_FENCE) && level.getBlockState(center.above()).is(Blocks.BEEHIVE) && level.getBlockState(center.above()).getValue(BeehiveBlock.HONEY_LEVEL)==5,"fence and native full honey hive at token floor");}
        void presentation(){for(var kind:LbcBeeDropItem.Kind.values()){var s=new ItemStack(kind.item());var data=s.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();require(data.size()==2 && data.getIntOr("bees",0)==1 && data.getIntOr("drop",0)==1 && LbcBeeDropItem.matches(s),"exact native source flags");
                if(kind==LbcBeeDropItem.Kind.NORMAL){require(Identifier.parse("lbc:drop_not_trap").equals(s.get(DataComponents.ITEM_MODEL)) && Identifier.parse("lbc:tier_f").equals(s.get(DataComponents.TOOLTIP_STYLE)),"normal model/tier");require(s.getHoverName().getContents() instanceof net.minecraft.network.chat.contents.TranslatableContents name && name.getKey().equals("drop_bee") && !s.getHoverName().getStyle().isItalic() && s.getHoverName().getStyle().getColor().getValue()==0xffff55,"normal translated name");var lore=s.getOrDefault(DataComponents.LORE,net.minecraft.world.item.component.ItemLore.EMPTY).lines();require(lore.size()==1 && lore.getFirst().getContents() instanceof net.minecraft.network.chat.contents.TranslatableContents row && row.getKey().equals("trap_desc"),"source lore");}
                else require(Identifier.parse("minecraft:barrier").equals(s.get(DataComponents.ITEM_MODEL)) && !s.has(DataComponents.CUSTOM_NAME) && !s.has(DataComponents.TOOLTIP_STYLE) && s.getOrDefault(DataComponents.LORE,net.minecraft.world.item.component.ItemLore.EMPTY).lines().isEmpty(),"legacy plain barrier");
                var loot=game.lbc().rollTable(level,origin,alpha,kind==LbcBeeDropItem.Kind.NORMAL?"lbc:ported/bees_drop":"lbc:ported/bees_drop_old");require(loot.size()==1 && loot.getFirst().getCount()==1 && ItemStack.isSameItemSameComponents(s,loot.getFirst()),"complete public leaf "+kind);
            }for(var v:List.of(Items.BARRIER,Items.REPEATING_COMMAND_BLOCK,Items.PAPER))require(!LbcBeeDropItem.matches(new ItemStack(v)),"unflagged vanilla lookalike rejected");}
        boolean honey(ItemStack s){return s.is(Items.HONEY_BLOCK)||s.is(Items.HONEY_BOTTLE)||s.is(Items.HONEYCOMB)||s.is(Items.HONEYCOMB_BLOCK);}
        Set<Entity> baseline(){var set=Collections.newSetFromMap(new IdentityHashMap<Entity,Boolean>());level.getAllEntities().forEach(set::add);return set;}
        List<ItemEntity> newItems(Set<Entity> before){var out=new ArrayList<ItemEntity>();for(var e:level.getAllEntities())if(!before.contains(e) && e instanceof ItemEntity i)out.add(i);return out;}
        void nativeDeath(Bee bee){var before=baseline();int prior=kills(beta);require(bee.hurtServer(level,bee.damageSources().playerAttack(beta),1000) && bee.isDeadOrDying() && bee.getKillCredit()==beta && kills(beta)==prior+1,"actual native bee death credits actual killer");var loot=newItems(before);int count=loot.stream().mapToInt(i->i.getItem().getCount()).sum();require(count>=1 && count<=4 && loot.stream().allMatch(i->honey(i.getItem()) && ItemStack.isSameItemSameComponents(i.getItem(),new ItemStack(i.getItem().getItem()))),"per-bee native honey loot1..4, no extra components");loot.forEach(Entity::discard);bee.discard();}
        void rewards(){var table=game.server().reloadableRegistries().getLootTable(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.LOOT_TABLE,Identifier.parse("lbc:honey")));boolean bonus=false;var types=new HashSet<net.minecraft.world.item.Item>();
            for(int seed=1;seed<=32;seed++){int[] counts=new int[2];for(int l=0;l<2;l++){var params=new net.minecraft.world.level.storage.loot.LootParams.Builder(level).withParameter(net.minecraft.world.level.storage.loot.parameters.LootContextParams.ORIGIN,origin).withParameter(net.minecraft.world.level.storage.loot.parameters.LootContextParams.THIS_ENTITY,alpha).withParameter(net.minecraft.world.level.storage.loot.parameters.LootContextParams.DAMAGE_SOURCE,alpha.damageSources().generic()).withLuck(l==0?0:10).create(net.minecraft.world.level.storage.loot.parameters.LootContextParamSets.ENTITY);var rolled=table.getRandomItems(params,seed*0x9E3779B97F4A7C15L);for(var s:rolled){require(honey(s),"closed vanilla honey reward table");types.add(s.getItem());counts[l]+=s.getCount();}require(counts[l]>=1 && counts[l]<=(l==0?4:44),"native uniform rolls/bonus bounds");}require(counts[1]>=counts[0],"same seeded native luck adds bonus rolls");bonus|=counts[1]>counts[0];}require(bonus && types.size()==4,"native luck bonus and all four honey rewards");
            reset();var bees=batch();defaults(bees);for(var bee:bees)nativeDeath(bee); // seven independent actual deaths, not seven table-only rolls
        }
        void containers(){reset();level.setBlock(center,Blocks.CHEST.defaultBlockState(),818);level.setBlock(center.above(),Blocks.CHEST.defaultBlockState(),818);var lower=(net.minecraft.world.Container)level.getBlockEntity(center);var upper=(net.minecraft.world.Container)level.getBlockEntity(center.above());require(lower!=null && upper!=null,"native displacement containers");lower.setItem(0,new ItemStack(Items.DIAMOND,7));upper.setItem(0,new ItemStack(Items.EMERALD,11));var before=baseline();defaults(batch());var loot=newItems(before);require(loot.stream().filter(i->i.getItem().is(Items.DIAMOND)).mapToInt(i->i.getItem().getCount()).sum()==0 && loot.stream().filter(i->i.getItem().is(Items.EMERALD)).mapToInt(i->i.getItem().getCount()).sum()==11,"native replace suppresses lower inventory, destroy spills upper: "+loot.stream().map(i->i.getItem().toString()).toList());require(loot.stream().anyMatch(i->i.getItem().is(Items.CHEST)),"destroy hive command emits old chest block loot");loot.forEach(Entity::discard);}
        void hives(){reset();var bees=batch();var hive=(BeehiveBlockEntity)level.getBlockEntity(center.above());require(hive!=null && hive.isEmpty(),"source new hive has no invented occupants");var source=bees.getFirst();var uuid=source.getUUID();hive.addOccupant(source);require(source.isRemoved() && hive.getOccupantCount()==1 && game.items().beeDrops().storedCount()>=1,"actual native entry stores bee and removes live instance");
            var occupants=hive.collectComponents().get(DataComponents.BEES);require(occupants!=null,"native hive-item Bees component");
            hive.emptyAllLivingFromHive(null,hive.getBlockState(),BeehiveBlockEntity.BeeReleaseStatus.EMERGENCY);capture();var released=game.items().beeDrops().snapshot().stream().filter(b->!b.isRemoved() && b.hasHive() && center.above().equals(b.getHivePos())).toList();require(hive.isEmpty() && released.size()==1,"native emergency exit creates one real bee");var bee=released.getFirst();require(!bee.getUUID().equals(uuid) && bee.hasNectar() && saved(bee,level).getStringOr("DeathLootTable","").equals("lbc:honey") && game.items().beeDrops().owner(bee)==alpha,"native UUID replacement retains nectar/deathloot/actual author");nativeDeath(bee);
            var transferPos=center.offset(2,1,0);level.setBlock(transferPos,Blocks.BEEHIVE.defaultBlockState(),818);var transfer=(BeehiveBlockEntity)level.getBlockEntity(transferPos);require(transfer!=null,"native destination hive");for(var occupant:occupants.bees())transfer.storeBee(occupant);require(transfer.getOccupantCount()==1,"native hive item component transfer");transfer.emptyAllLivingFromHive(null,transfer.getBlockState(),BeehiveBlockEntity.BeeReleaseStatus.EMERGENCY);capture();var transferred=game.items().beeDrops().snapshot().stream().filter(b->!b.isRemoved() && transferPos.equals(b.getHivePos())).toList();require(transferred.size()==1 && game.items().beeDrops().owner(transferred.getFirst())==alpha && saved(transferred.getFirst(),level).getStringOr("DeathLootTable","").equals("lbc:honey"),"native item transfer retains managed cause and reward");nativeDeath(transferred.getFirst());
            var child=bees.get(1).getBreedOffspring(level,bees.get(2));require(child!=null,"native bee offspring factory");try{require(!LbcBeeDrop.managed(child) && game.items().beeDrops().owner(child)==null && !saved(child,level).getStringOr("DeathLootTable","").equals("lbc:honey"),"ordinary offspring has no invented custom loot or author inheritance");}finally{child.discard();}
            hive.addOccupant(bees.get(1));alpha.teleportTo(level,origin.x,origin.y+1,origin.z+2,Set.of(),0,0,true);var mined=net.minecraft.stats.Stats.BLOCK_MINED.get(Blocks.BEEHIVE);int oldMined=alpha.getStats().getValue(mined);
            try{require(alpha.gameMode.destroyBlock(center.above()),"native player destroys occupied source hive");capture();var angry=game.items().beeDrops().snapshot().stream().filter(b->!b.isRemoved() && center.above().equals(b.getHivePos()) && b.getTarget()==alpha).toList();require(!angry.isEmpty(),"actual hive destruction releases native retaliation at thrower");nativeDeath(angry.getFirst());}finally{alpha.getStats().setValue(alpha,mined,oldMined);alpha.teleportTo(level,origin.x+20,origin.y,origin.z,Set.of(),0,0,true);}
        }
        void multiFlag(){reset();beta.teleportTo(level,origin.x-1,origin.y,origin.z,Set.of(),0,0,true);var before=baseline();var both=drop(2);var data=both.getItem().getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();data.putInt("library",1);both.getItem().set(DataComponents.CUSTOM_DATA,CustomData.of(data));
            require(game.items().specialDrops().spawn(both) && both.getItem().getCount()==1,"Library plus bees one source debit");capture();require(mine.size()==7 && level.getBlockState(center).is(Blocks.OAK_FENCE) && level.getBlockState(center.above(3)).is(Blocks.OAK_WOOD),"source Library table replaced by later bee fence while Library roof remains");both.discard();
            var rewards=new ArrayList<Entity>();for(var e:level.getAllEntities())if(!before.contains(e) && LbcLibraryDrop.managed(e))rewards.add(e);require(rewards.size()==3,"independent earlier Library rewards");rewards.forEach(Entity::discard);beta.teleportTo(level,origin.x+22,origin.y,origin.z,Set.of(),0,0,true);
        }
        Cow cow(Vec3 at){var cow=new Cow(EntityTypes.COW,level);cow.setPos(at);cow.setNoAi(true);cow.setNoGravity(true);require(level.addFreshEntity(cow),"native disposable sting victim");return cow;}
        void stings(){reset();var bees=batch();for(var b:bees){b.setNoAi(true);b.setNoGravity(true);}var bee=bees.getFirst();var victim=cow(origin.add(0,4,0));try{victim.setHealth(1);int before=kills(alpha);require(bee.doHurtTarget(level,victim) && victim.isDeadOrDying() && victim.getKillCredit()==alpha && kills(alpha)==before+1,"actual native lethal sting credits actual thrower");}finally{victim.discard();}
            int stingIndex=1;for(boolean outOfWorld:List.of(false,true))for(boolean newer:List.of(false,true)){var b=bees.get(stingIndex++);var target=cow(origin.add(0,4,0));try{require(b.doHurtTarget(level,target),"actual native nonlethal sting");if(level.getDifficulty()==net.minecraft.world.Difficulty.NORMAL || level.getDifficulty()==net.minecraft.world.Difficulty.HARD)require(target.hasEffect(net.minecraft.world.effect.MobEffects.POISON),"native sting accepts sourced poison");if(newer){target.setInvulnerableTime(0);target.damageCooldownTime=0;target.hurtServer(level,target.damageSources().playerAttack(beta),1);}target.setHealth(1);target.setInvulnerableTime(0);target.damageCooldownTime=0;int before=kills(newer?beta:alpha);target.hurtServer(level,outOfWorld?target.damageSources().fellOutOfWorld():target.damageSources().fall(),1000);require(target.isDeadOrDying() && target.getKillCredit()==(newer?beta:alpha) && kills(newer?beta:alpha)==before+1,"actual sting/poison fall/void attribution and newer attacker "+outOfWorld+"/"+newer);}finally{game.items().indirectKills().clear(target);target.discard();}}
            var guarded=bees.get(5);for(String tag:List.of("spectator","rcdenyalways","sauvojen_tuntija","strict_map_object","magic_academy","transformator")){var npc=cow(origin.add(0,4,0));npc.entityTags().add(tag);try{require(!guarded.doHurtTarget(level,npc) && npc.getHealth()==npc.getMaxHealth() && !npc.hasEffect(net.minecraft.world.effect.MobEffects.POISON),"role blocks native sting before damage/poison "+tag);}finally{npc.discard();}}
            var board=game.server().getScoreboard();var oldAlpha=alpha.getTeam();var oldBeta=beta.getTeam();require(board.getPlayerTeam("codex_bees_probe")==null,"fixture team available");var team=board.addPlayerTeam("codex_bees_probe");team.setAllowFriendlyFire(false);try{board.addPlayerToTeam(alpha.getScoreboardName(),team);board.addPlayerToTeam(beta.getScoreboardName(),team);require(!guarded.doHurtTarget(level,beta) && beta.getHealth()==1000 && !beta.hasEffect(net.minecraft.world.effect.MobEffects.POISON),"allied native sting blocked");require(guarded.doHurtTarget(level,alpha) && alpha.getHealth()<1000,"thrower retains native self retaliation");}finally{board.removePlayerTeam(team);if(oldAlpha!=null)board.addPlayerToTeam(alpha.getScoreboardName(),oldAlpha);if(oldBeta!=null)board.addPlayerToTeam(beta.getScoreboardName(),oldBeta);alpha.removeAllEffects();beta.removeAllEffects();alpha.setHealth(1000);beta.setHealth(1000);}
        }
        void guards(){var stale=drop(2);stale.entityTags().add("skywars2.items.stale-fixture");require(!game.items().specialDrops().spawn(stale) && stale.getItem().getCount()==2,"stale token no debit");stale.discard();var fake=drop(2);fake.makeFakeItem();require(!game.items().specialDrops().spawn(fake),"native give visual guard");fake.discard();var remote=drop(2);int x=(center.getX()>>4)+128,z=(center.getZ()>>4)+128;while(level.getChunkSource().getChunkNow(x,z)!=null)x+=128;remote.setPos(x*16+8,origin.y,z*16+8);require(!game.items().specialDrops().spawn(remote) && remote.getItem().getCount()==2 && level.getChunkSource().getChunkNow(x,z)==null,"unresident native token neither loads nor debits");remote.discard();}
        boolean step(){require(game.playing(),"actual match retained");int now=game.server().getTickCount();if(now==lastTick)return false;lastTick=now;switch(phase){
            case 0->{presentation();guards();containers();rewards();hives();stings();multiFlag();reset();var legacy=token(level,origin,2,alpha,LbcBeeDropItem.Kind.OLD);tokens.add(legacy);require(game.items().specialDrops().spawn(legacy) && legacy.getItem().getCount()==1,"legacy actual dispatch");capture();defaults(new ArrayList<>(mine));legacy.discard();reset();stack=drop(2);phase++;}
            case 1->{capture();require(stack.getItem().getCount()==1 && mine.size()==7,"actual first tick one debit and seven bees");for(var b:mine)b.setStayOutOfHiveCountdown(100);phase++;}
            case 2->{capture();require(stack.isRemoved() && mine.size()==14,"actual second tick consumes final unit");for(var b:mine)if(!b.isRemoved())frozen.put(b,b.position());game.items().timeStop().begin(level,200);paused=drop(2);phase++;}
            case 3->{require(paused.getItem().getCount()==2 && frozen.entrySet().stream().allMatch(e->!e.getKey().isRemoved() && e.getKey().position().distanceTo(e.getValue())<1e-8),"time stop freezes native bees and pending debit");if(++wait>=3){paused.discard();game.items().timeStop().end(level);clearMine();unloaded=drop(2);game.items().specialDrops().unloaded(unloaded);phase++;}}
            case 4->{require(!unloaded.isRemoved() && unloaded.getItem().getCount()==2,"unloaded pending token cannot replay");unloaded.discard();var b=batch().getFirst();game.items().beeDrops().unloaded(b);require(!game.items().beeDrops().snapshot().contains(b),"resident bee unload detaches");game.items().beeDrops().loaded(b);require(game.items().beeDrops().snapshot().contains(b),"same epoch bee load restores");b.entityTags().removeIf(t->t.startsWith("skywars2.items."));b.entityTags().add("skywars2.items.stale-fixture");game.items().beeDrops().unloaded(b);game.items().beeDrops().loaded(b);require(b.isRemoved(),"stale native bee quietly rejected");return true;}
            default->throw new IllegalStateException("Unknown Bees phase "+phase);
        }return false;}
        public void close(){close(false);}
        void close(boolean keepBeeFixture){game.items().timeStop().end(level);tokens.forEach(Entity::discard);if(!keepBeeFixture){clearMine();restoreBlocks();}
            var leftovers=new ArrayList<Entity>();for(var e:level.getAllEntities())if(!existing.contains(e) && !(e instanceof ServerPlayer) && !(keepBeeFixture && e instanceof Bee) && Math.abs(e.getX()-origin.x)<8 && Math.abs(e.getZ()-origin.z)<8)leftovers.add(e);leftovers.forEach(Entity::discard);
            level.getGameRules().set(GameRules.MOB_DROPS,mobDrops,game.server());level.getGameRules().set(GameRules.BLOCK_DROPS,blockDrops,game.server());alphaState.restore(game);betaState.restore(game);alpha.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.LUCK).setBaseValue(alphaLuck);beta.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.LUCK).setBaseValue(betaLuck);alpha.getStats().setValue(alpha,net.minecraft.stats.Stats.CUSTOM.get(net.minecraft.stats.Stats.MOB_KILLS),alphaKills);beta.getStats().setValue(beta,net.minecraft.stats.Stats.CUSTOM.get(net.minecraft.stats.Stats.MOB_KILLS),betaKills);}
        void restoreBlocks(){for(var e:blocks.entrySet()){if(level.getBlockEntity(e.getKey()) instanceof net.minecraft.world.Container c)c.clearContent();game.maps().restoreSnapshot(level,e.getKey(),e.getValue());}for(long key:forced)level.setChunkForced(net.minecraft.world.level.ChunkPos.getX(key),net.minecraft.world.level.ChunkPos.getZ(key),false);}
    }
    private static void closeFailure(State state,Throwable error){try{state.close();}catch(Throwable cleanup){if(error!=cleanup)error.addSuppressed(cleanup);}finally{running=null;stopping=null;}}
    public static void run(GameController game){require(running==null && stopping==null,"already running");running=new State(game);try{running.initialize();}catch(RuntimeException|Error error){closeFailure(running,error);throw error;}}
    public static void tick(GameController game){if(stopping!=null){var state=stopping;if(game.server().getTickCount()==state.lastTick)return;try{game.items().timeStop().end(state.level);var bees=state.batch();state.defaults(bees);stopHive=(BeehiveBlockEntity)state.level.getBlockEntity(state.center.above());stopHive.addOccupant(bees.getFirst());stopHive.storeBee(BeehiveBlockEntity.Occupant.create(0));stopBees=bees.stream().filter(b->!b.isRemoved()).toList();require(stopHive.getOccupantCount()==2 && stopBees.size()==6,"native stored/live stop probe");stopEpoch=game.items().epoch();state.close(true);stoppedFixture=state;stopXp=state.alpha.totalExperience+state.beta.totalExperience;game.items().timeStop().begin(state.level,200);stopToken=token(state.level,state.origin.add(0,4,0),3,state.alpha,LbcBeeDropItem.Kind.NORMAL);require(!game.items().specialDrops().spawn(stopToken) && stopToken.getItem().getCount()==3,"pending freeze retains unit count");stopping=null;SkyWars2.LOGGER.info("[check] PASS bees-drop-stop-probe");}catch(Throwable error){closeFailure(state,error);SkyWars2.LOGGER.error("[check] FAIL bees-drop-stop-probe",error);}return;}
        if(running==null)return;var state=running;try{if(state.step()){state.close();running=null;SkyWars2.LOGGER.info("[check] PASS bees-drop");}}catch(Throwable error){closeFailure(state,error);SkyWars2.LOGGER.error("[check] FAIL bees-drop",error);}}
    public static void stopProbe(GameController game){require(game.playing() && running==null && stopping==null,"actual match stop probe");stopping=new State(game);try{stopping.initialize();}catch(RuntimeException|Error error){closeFailure(stopping,error);throw error;}}
    public static void cleanup(GameController game){require(!game.items().currentEpoch(stopEpoch) && stopToken!=null && stopToken.getItem().getCount()==3 && game.items().beeDrops().trackedCount()==0 && game.items().beeDrops().storedCount()==0,"actual stop invalidates epoch and clears service without debit");require(stopBees.size()==6 && stopBees.stream().allMatch(Entity::isRemoved) && stopHive!=null && stopHive.getOccupantCount()==1,"actual quiet stop removes managed live/stored bees and preserves ordinary occupant");require(stoppedFixture.alpha.totalExperience+stoppedFixture.beta.totalExperience==stopXp,"quiet bee cleanup grants no XP");require(!game.items().specialDrops().spawn(stopToken),"stopped token cannot replay");stopToken.discard();stopToken=null;stopEpoch=null;stopBees=List.of();stopHive=null;if(stoppedFixture!=null){stoppedFixture.restoreBlocks();stoppedFixture=null;}SkyWars2.LOGGER.info("[check] PASS bees-drop-cleanup");}
}
